\set ON_ERROR_STOP on

-- 1. extension + schemas ------------------------------------------------------------------------
CREATE EXTENSION IF NOT EXISTS vector;
CREATE SCHEMA IF NOT EXISTS app;
CREATE SCHEMA IF NOT EXISTS checkpoints;
CREATE SCHEMA IF NOT EXISTS mem0;

-- 2. app tables (Alembic) --------------------------------------------------------------------------
SET search_path TO app, public;

BEGIN;

CREATE TABLE app.alembic_version (
    version_num VARCHAR(32) NOT NULL, 
    CONSTRAINT alembic_version_pkc PRIMARY KEY (version_num)
);

-- Running upgrade  -> 55e00450c61d

CREATE TABLE app.orgs (
    id UUID NOT NULL, 
    slug VARCHAR(64) NOT NULL, 
    display_name VARCHAR(200) NOT NULL, 
    email_domain VARCHAR(255), 
    is_personal BOOLEAN DEFAULT 'false' NOT NULL, 
    created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
    CONSTRAINT pk_orgs PRIMARY KEY (id), 
    CONSTRAINT uq_orgs_email_domain UNIQUE (email_domain), 
    CONSTRAINT uq_orgs_slug UNIQUE (slug)
);

CREATE TABLE app.users (
    id UUID NOT NULL, 
    email VARCHAR(320) NOT NULL, 
    short_id VARCHAR(12) NOT NULL, 
    google_sub VARCHAR(64), 
    name VARCHAR(200), 
    picture_url TEXT, 
    org_id UUID NOT NULL, 
    settings JSONB DEFAULT '{}' NOT NULL, 
    created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
    last_login_at TIMESTAMP WITH TIME ZONE, 
    CONSTRAINT pk_users PRIMARY KEY (id), 
    CONSTRAINT ck_users_email_lowercase CHECK (email = lower(email)), 
    CONSTRAINT fk_users_org_id_orgs FOREIGN KEY(org_id) REFERENCES app.orgs (id), 
    CONSTRAINT uq_users_email UNIQUE (email), 
    CONSTRAINT uq_users_google_sub UNIQUE (google_sub), 
    CONSTRAINT uq_users_short_id UNIQUE (short_id)
);

CREATE INDEX ix_users_org_id ON app.users (org_id);

CREATE TABLE app.datasets (
    id UUID NOT NULL, 
    org_id UUID NOT NULL, 
    owner_id UUID NOT NULL, 
    project_id VARCHAR(128) NOT NULL, 
    dataset_id VARCHAR(1024) NOT NULL, 
    location VARCHAR(64) NOT NULL, 
    visibility VARCHAR(10) DEFAULT 'private' NOT NULL, 
    description TEXT, 
    schema_refreshed_at TIMESTAMP WITH TIME ZONE, 
    created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
    CONSTRAINT pk_datasets PRIMARY KEY (id), 
    CONSTRAINT ck_datasets_visibility CHECK (visibility IN ('private', 'org')), 
    CONSTRAINT fk_datasets_org_id_orgs FOREIGN KEY(org_id) REFERENCES app.orgs (id), 
    CONSTRAINT fk_datasets_owner_id_users FOREIGN KEY(owner_id) REFERENCES app.users (id), 
    CONSTRAINT uq_datasets_owner_id_project_id_dataset_id UNIQUE (owner_id, project_id, dataset_id)
);

CREATE INDEX ix_datasets_org_id ON app.datasets (org_id);

CREATE INDEX ix_datasets_owner_id ON app.datasets (owner_id);

CREATE TABLE app.rag_corpora (
    id UUID NOT NULL, 
    scope VARCHAR(10) NOT NULL, 
    org_id UUID NOT NULL, 
    user_id UUID, 
    display_name VARCHAR(200) NOT NULL, 
    corpus_name VARCHAR(300) NOT NULL, 
    created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
    CONSTRAINT pk_rag_corpora PRIMARY KEY (id), 
    CONSTRAINT ck_rag_corpora_scope CHECK (scope IN ('org', 'user')), 
    CONSTRAINT fk_rag_corpora_org_id_orgs FOREIGN KEY(org_id) REFERENCES app.orgs (id), 
    CONSTRAINT fk_rag_corpora_user_id_users FOREIGN KEY(user_id) REFERENCES app.users (id), 
    CONSTRAINT uq_rag_corpora_corpus_name UNIQUE (corpus_name), 
    CONSTRAINT uq_rag_corpora_display_name UNIQUE (display_name)
);

CREATE TABLE app.user_credentials (
    user_id UUID NOT NULL, 
    refresh_token_enc BYTEA NOT NULL, 
    scopes TEXT NOT NULL, 
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
    CONSTRAINT pk_user_credentials PRIMARY KEY (user_id), 
    CONSTRAINT fk_user_credentials_user_id_users FOREIGN KEY(user_id) REFERENCES app.users (id) ON DELETE CASCADE
);

CREATE TABLE app.chats (
    id UUID NOT NULL, 
    user_id UUID NOT NULL, 
    dataset_pk UUID, 
    model VARCHAR(200) NOT NULL, 
    title VARCHAR(300) DEFAULT 'New chat' NOT NULL, 
    created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
    CONSTRAINT pk_chats PRIMARY KEY (id), 
    CONSTRAINT fk_chats_dataset_pk_datasets FOREIGN KEY(dataset_pk) REFERENCES app.datasets (id) ON DELETE SET NULL, 
    CONSTRAINT fk_chats_user_id_users FOREIGN KEY(user_id) REFERENCES app.users (id) ON DELETE CASCADE
);

CREATE INDEX ix_chats_user_id ON app.chats (user_id);

CREATE TABLE app.dataset_notes (
    id UUID NOT NULL, 
    dataset_pk UUID NOT NULL, 
    author_id UUID NOT NULL, 
    visibility VARCHAR(10) DEFAULT 'private' NOT NULL, 
    body TEXT NOT NULL, 
    created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
    CONSTRAINT pk_dataset_notes PRIMARY KEY (id), 
    CONSTRAINT ck_dataset_notes_visibility CHECK (visibility IN ('private', 'org')), 
    CONSTRAINT fk_dataset_notes_author_id_users FOREIGN KEY(author_id) REFERENCES app.users (id), 
    CONSTRAINT fk_dataset_notes_dataset_pk_datasets FOREIGN KEY(dataset_pk) REFERENCES app.datasets (id) ON DELETE CASCADE
);

CREATE INDEX ix_dataset_notes_dataset_pk ON app.dataset_notes (dataset_pk);

CREATE TABLE app.dataset_tables (
    id UUID NOT NULL, 
    dataset_pk UUID NOT NULL, 
    table_name VARCHAR(1024) NOT NULL, 
    description TEXT, 
    num_rows BIGINT, 
    partition_column VARCHAR(300), 
    cluster_columns JSONB DEFAULT '[]' NOT NULL, 
    columns JSONB DEFAULT '[]' NOT NULL, 
    refreshed_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
    CONSTRAINT pk_dataset_tables PRIMARY KEY (id), 
    CONSTRAINT fk_dataset_tables_dataset_pk_datasets FOREIGN KEY(dataset_pk) REFERENCES app.datasets (id) ON DELETE CASCADE, 
    CONSTRAINT uq_dataset_tables_dataset_pk_table_name UNIQUE (dataset_pk, table_name)
);

CREATE TABLE app.examples (
    id UUID NOT NULL, 
    org_id UUID NOT NULL, 
    created_by UUID NOT NULL, 
    dataset_pk UUID NOT NULL, 
    visibility VARCHAR(10) DEFAULT 'private' NOT NULL, 
    question TEXT NOT NULL, 
    sql TEXT NOT NULL, 
    notes TEXT DEFAULT '' NOT NULL, 
    content_hash VARCHAR(64) NOT NULL, 
    gcs_uri TEXT, 
    corpus_id UUID, 
    rag_file_name VARCHAR(300), 
    verified_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
    created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
    CONSTRAINT pk_examples PRIMARY KEY (id), 
    CONSTRAINT ck_examples_visibility CHECK (visibility IN ('private', 'org')), 
    CONSTRAINT fk_examples_corpus_id_rag_corpora FOREIGN KEY(corpus_id) REFERENCES app.rag_corpora (id), 
    CONSTRAINT fk_examples_created_by_users FOREIGN KEY(created_by) REFERENCES app.users (id), 
    CONSTRAINT fk_examples_dataset_pk_datasets FOREIGN KEY(dataset_pk) REFERENCES app.datasets (id) ON DELETE CASCADE, 
    CONSTRAINT fk_examples_org_id_orgs FOREIGN KEY(org_id) REFERENCES app.orgs (id)
);

CREATE INDEX ix_examples_org_dataset ON app.examples (org_id, dataset_pk);

CREATE TABLE app.query_log (
    id BIGSERIAL NOT NULL, 
    user_id UUID NOT NULL, 
    chat_id UUID, 
    dataset_pk UUID, 
    job_id VARCHAR(300) NOT NULL, 
    model VARCHAR(200), 
    gb_processed FLOAT NOT NULL, 
    cost_usd FLOAT NOT NULL, 
    created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
    CONSTRAINT pk_query_log PRIMARY KEY (id), 
    CONSTRAINT fk_query_log_chat_id_chats FOREIGN KEY(chat_id) REFERENCES app.chats (id) ON DELETE SET NULL, 
    CONSTRAINT fk_query_log_dataset_pk_datasets FOREIGN KEY(dataset_pk) REFERENCES app.datasets (id) ON DELETE SET NULL, 
    CONSTRAINT fk_query_log_user_id_users FOREIGN KEY(user_id) REFERENCES app.users (id) ON DELETE CASCADE
);

CREATE INDEX ix_query_log_user_created ON app.query_log (user_id, created_at);

INSERT INTO app.alembic_version (version_num) VALUES ('55e00450c61d') RETURNING app.alembic_version.version_num;

COMMIT;

